import { useState, useEffect, type FormEvent } from 'react';
import { useNavigate, Navigate } from 'react-router-dom';
import { Lock, Shield } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { useI18n } from '@/i18n/I18nContext';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { toast } from 'sonner';

const AUTH_KEY = '__app_ledlight_admin_auth';
const PASSWORD_KEY = '__app_ledlight_admin_password';
const DEFAULT_PASSWORD = 'admin123';

export function getAdminPassword(): string {
  try {
    const saved = scopedStorage.getItem(PASSWORD_KEY);
    if (saved && typeof saved === 'string' && saved.length >= 6) {
      return saved;
    }
  } catch {
    // ignore
  }
  return DEFAULT_PASSWORD;
}

export { PASSWORD_KEY, DEFAULT_PASSWORD };

export default function AdminLoginPage() {
  const { adminT, adminLanguage, setAdminLanguage } = useI18n();
  const navigate = useNavigate();
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);

  // Check if already logged in
  useEffect(() => {
    try {
      const auth = scopedStorage.getItem(AUTH_KEY);
      if (auth === 'true') {
        navigate('/admin/dashboard', { replace: true });
      }
    } catch {
      // ignore
    }
  }, [navigate]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    setError('');

    if (password === getAdminPassword()) {
      try {
        scopedStorage.setItem(AUTH_KEY, 'true');
      } catch {
        // ignore
      }
      toast.success(adminT('admin.loginSuccessful'));
      navigate('/admin/dashboard', { replace: true });
    } else {
      setError(adminT('admin.loginError'));
    }
  };

  if (isAuthenticated === true) {
    return <Navigate to="/admin/dashboard" replace />;
  }

  return (
    <div className="admin-theme min-h-screen bg-background flex items-center justify-center px-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-primary/10 mb-4">
            <Shield className="size-8 text-primary" />
          </div>
          <h1 className="text-2xl font-bold text-foreground mb-2">{adminT('admin.adminPanel')}</h1>
           <p className="text-sm text-muted-foreground">{adminT('admin.adminTitle')}</p>
        </div>

        <Card className="border-border/40 bg-card shadow-xl">
          <CardHeader className="pb-4">
            <CardTitle className="text-lg">{adminT('admin.login')}</CardTitle>
            <CardDescription>{adminT('admin.enterPassword')}</CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="text-xs font-medium text-foreground mb-1.5 block">
                  {adminT('admin.password')}
                </label>
                <div className="relative">
                  <Lock className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="••••••••"
                    className="pl-9 bg-background/60"
                    autoFocus
                  />
                </div>
                {error && <p className="text-xs text-destructive mt-1.5">{error}</p>}
              </div>

              <Button
                type="submit"
                className="w-full bg-primary hover:bg-primary/90 text-primary-foreground"
              >
                {adminT('admin.loginBtn')}
              </Button>

              <p className="text-[10px] text-center text-muted-foreground">
                默认密码：<span className="font-mono text-foreground/70">admin123</span>
              </p>
            </form>
          </CardContent>
        </Card>

        <div className="text-center mt-6">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate('/')}
            className="text-xs text-muted-foreground"
          >
             ← 返回网站
          </Button>
        </div>
      </div>
    </div>
  );
}
